import type { ComponentPropsWithoutRef, ElementType, ReactNode } from "react";

import { cn } from "@/lib/utils";

type SectionSize = "narrow" | "default" | "wide";
type SectionBackground = "transparent" | "muted" | "white" | "dark";

interface SectionProps<T extends ElementType = "section"> {
	as?: T;
	size?: SectionSize;
	background?: SectionBackground;
	className?: string;
	children: ReactNode;
}

const sizeClasses: Record<SectionSize, string> = {
	narrow: "max-w-5xl",
	default: "max-w-7xl",
	wide: "max-w-full",
};

const backgroundClasses: Record<SectionBackground, string> = {
	transparent: "",
	muted: "bg-neutral-50",
	white: "bg-white",
	dark: "bg-neutral-950",
};

export function Section<T extends ElementType = "section">({
	as,
	size = "default",
	background = "transparent",
	className,
	children,
	...props
}: SectionProps<T> & Omit<ComponentPropsWithoutRef<T>, keyof SectionProps<T>>) {
	const Component = as || "section";

	return (
		<Component
			className={cn(
				"px-6 py-24 md:px-12 lg:px-24",
				backgroundClasses[background],
				className,
			)}
			{...props}
		>
			<div className={cn("mx-auto", sizeClasses[size])}>{children}</div>
		</Component>
	);
}

import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

interface SectionHeaderProps {
	label?: string;
	title: ReactNode;
	description?: ReactNode;
	action?: ReactNode;
	align?: "left" | "center";
	className?: string;
}

export function SectionHeader({
	label,
	title,
	description,
	action,
	align = "left",
	className,
}: SectionHeaderProps) {
	return (
		<div className={cn("mb-12 flex w-full flex-col", className)}>
			{label && (
				<div className="flex w-full items-center justify-between pb-5">
					<div className="flex items-center gap-2">
						<span className="h-px w-8 bg-primary" />
						<span className="font-bold font-sans text-primary text-xs uppercase tracking-[0.2em]">
							{label}
						</span>
					</div>
					{action && <div className="ml-auto">{action}</div>}
				</div>
			)}

			<div className="mb-8 h-px w-full bg-neutral-200" />

			<div
				className={cn(
					"flex flex-col justify-between gap-8 lg:flex-row lg:items-start lg:gap-16",
					align === "center" && "text-center",
				)}
			>
				<h2
					className={cn(
						"max-w-3xl font-display font-normal text-3xl text-neutral-900 leading-[1.05] tracking-tight md:text-4xl lg:text-5xl",
						align === "center" && "mx-auto",
					)}
				>
					{title}
				</h2>
				{description && (
					<div
						className={cn(
							"flex-shrink-0 lg:max-w-sm lg:pt-2",
							align === "center" && "mx-auto lg:max-w-md",
						)}
					>
						<p className="font-sans text-base text-neutral-600 leading-relaxed">
							{description}
						</p>
					</div>
				)}
			</div>
		</div>
	);
}

